def count_Primes_nums(n):
    """
    Returns the number of prime numbers less than the given non-negative number n.

    :param n: int - a non-negative integer
    :return: int - the count of prime numbers less than n
    """
    if n < 2:
        return 0
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False
    return sum(is_prime)
